<script setup lang="ts">
definePageMeta({layout:'workspace'})
const db=useSupabaseClient()
const {platformAdmin,load:reloadSchools}=useSchool()
type School={id:string;name:string;code:string|null;allow_student_self_registration:boolean;deactivated_at:string|null;created_at:string}
type Request={id:string;school_name:string;school_domain:string;contact_name:string;contact_email:string;contact_position:string;status:string;created_at:string;requester_id:string|null;created_school_id:string|null}
const tab=ref('schools'),schools=ref<School[]>([]),requests=ref<Request[]>([]),search=ref(''),statusFilter=ref('all'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const inviteBusy=ref('');async function inviteAdmin(r:Request){if(inviteBusy.value||!r.created_school_id)return;inviteBusy.value=r.id;error.value='';notice.value='';try{const {data:{session}}=await db.auth.getSession();if(!session)throw new Error('Sign in required');const result=await $fetch<{message:string}>('/api/schools/invite-admin',{method:'POST',headers:{Authorization:'Bearer '+session.access_token},body:{requestId:r.id}});notice.value=result.message}catch(e:any){error.value=e?.data?.statusMessage||e?.data?.message||e?.message||'Unable to send invitation'}finally{inviteBusy.value=''}}
const rejectedAction=ref<{request:Request;action:'reconsider'|'delete'}|null>(null)
async function confirmRejectedAction(){const selected=rejectedAction.value;if(!selected||busy.value||!platformAdmin.value)return;busy.value=true;error.value='';notice.value='';try{const result=await db.rpc('manage_rejected_school_request',{p_request_id:selected.request.id,p_action:selected.action});if(result.error)throw result.error;rejectedAction.value=null;await load();notice.value=selected.action==='delete'?'Rejected request deleted':'Request returned to Pending'}catch(e:any){error.value=e?.message||'Unable to update request';rejectedAction.value=null}finally{busy.value=false}}
const reviewAction=ref<{request:Request;approve:boolean}|null>(null)
const modalOpen=ref(false),editing=ref(false),confirmSave=ref(false)
const selectedId=ref(''),name=ref(''),code=ref(''),selfRegistration=ref(false),domains=ref<{domain:string;is_primary:boolean;is_verified:boolean}[]>([])
const selected=computed(()=>schools.value.find(s=>s.id===selectedId.value))
const filteredSchools=computed(()=>schools.value.filter(s=>(s.name+' '+(s.code||'')).toLowerCase().includes(search.value.toLowerCase())))
const filteredRequests=computed(()=>requests.value.filter(r=>statusFilter.value==='all'||r.status===statusFilter.value))
function resetEdit(){if(selected.value){name.value=selected.value.name;code.value=selected.value.code||''}editing.value=false}
function choose(s:School){selectedId.value=s.id;name.value=s.name;code.value=s.code||'';selfRegistration.value=s.allow_student_self_registration;editing.value=false;modalOpen.value=true;void loadDomains()}
async function loadDomains(){domains.value=[];if(!selectedId.value)return;const r=await db.from('school_email_domains').select('domain,is_primary,is_verified').eq('school_id',selectedId.value).order('domain');if(r.error)error.value=r.error.message;else domains.value=r.data||[]}
async function load(){if(!platformAdmin.value)return;loading.value=true;error.value='';try{const [s,r]=await Promise.all([db.from('schools').select('id,name,code,allow_student_self_registration,deactivated_at,created_at').order('name'),db.from('school_requests').select('id,school_name,school_domain,contact_name,contact_email,contact_position,status,created_at,requester_id,created_school_id').order('created_at',{ascending:false})]);if(s.error)throw s.error;if(r.error)throw r.error;schools.value=s.data||[];requests.value=r.data||[];if(selectedId.value){const updated=schools.value.find(s=>s.id===selectedId.value);if(updated){name.value=updated.name;code.value=updated.code||'';selfRegistration.value=updated.allow_student_self_registration}}}catch(e:any){error.value=e.message||'Unable to load schools'}finally{loading.value=false}}
async function save(){if(!platformAdmin.value||!selectedId.value||busy.value)return;confirmSave.value=false;busy.value=true;error.value='';notice.value='';try{const r=await db.rpc('update_school_settings',{p_school_id:selectedId.value,p_name:name.value,p_code:code.value,p_allow_student_registration:selfRegistration.value});if(r.error)throw r.error;await load();await reloadSchools();notice.value='School settings saved';editing.value=false;modalOpen.value=false}catch(e:any){error.value=e.message||'Unable to save school'}finally{busy.value=false}}
async function review(){const choice=reviewAction.value;if(!choice||!platformAdmin.value||busy.value)return;const {request:r,approve}=choice;busy.value=true;error.value='';notice.value='';try{const {data:{session},error:sessionError}=await db.auth.getSession();if(sessionError||!session?.access_token)throw new Error('Your session has expired. Please sign in again before reviewing school requests.');const {data:{user},error:userError}=await db.auth.getUser();if(userError||!user)throw new Error('Your session is no longer valid. Please sign in again.');const {data:isAdmin,error:adminError}=await db.rpc('is_platform_admin');if(adminError)throw adminError;if(isAdmin!==true)throw new Error('Platform Administrator access is required.');const result=await db.rpc('review_school_request',{p_request_id:r.id,p_approve:approve,p_review_notes:null});if(result.error)throw result.error;await load();await reloadSchools();reviewAction.value=null;notice.value=approve?'School approved. Send the initial administrator invitation.':'School request rejected'}catch(e:any){error.value=e.message||'Unable to review request'}finally{busy.value=false}}
watch(platformAdmin,()=>{void load()},{immediate:true})
</script>
<template><div class="space-y-6"><div><h1 class="text-2xl font-bold">Schools</h1><p class="text-sm text-[var(--muted)]">Platform administration · Registered schools and onboarding requests</p></div><UiPanel v-if="!platformAdmin">Platform Administrator access is required.</UiPanel><template v-else><div class="flex flex-wrap gap-2"><button v-for="t in [{id:'schools',label:'All Schools'},{id:'requests',label:'School Requests'}]" :key="t.id" class="rounded-xl border border-[var(--border)] px-4 py-2 text-sm font-semibold" :class="tab===t.id?'bg-blue-600 text-white':''" @click="tab=t.id">{{t.label}}<span v-if="t.id==='requests'"> ({{requests.filter(r=>r.status==='pending').length}})</span></button></div><p v-if="error" class="text-red-600" role="alert">{{error}}</p><p v-if="notice" class="text-green-600" role="status">{{notice}}</p><p v-if="loading">Loading schools…</p><UiPanel v-if="tab==='schools'"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">Registered schools ({{schools.length}})</h2><input v-model="search" placeholder="Search schools" aria-label="Search schools" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></div><div v-for="s in filteredSchools" :key="s.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border)] py-4"><div><p class="font-semibold">{{s.name}}</p><p class="text-sm text-[var(--muted)]">{{s.code||'No code'}} · {{s.deactivated_at?'Inactive':'Active'}}</p></div><button class="rounded-lg border border-[var(--border)] p-2 text-blue-600" aria-label="View school" title="View school" @click="choose(s)"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="3" y="2" width="18" height="20" rx="2"/><circle cx="12" cy="10" r="3"/><path d="M7 18a5 5 0 0 1 10 0"/></svg></button></div><p v-if="!filteredSchools.length" class="text-sm text-[var(--muted)]">No matching schools.</p></UiPanel><UiPanel v-else-if="tab==='requests'"><div class="mb-4 flex flex-wrap justify-between gap-3"><h2 class="text-lg font-bold">School registration requests</h2><select v-model="statusFilter" aria-label="Request status" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></div><div v-for="r in filteredRequests" :key="r.id" class="border-b border-[var(--border)] py-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold">{{r.school_name}}</p><p class="text-sm text-[var(--muted)]">{{r.school_domain}} · {{r.contact_name}} ({{r.contact_position}}) · {{r.contact_email}}</p><p class="mt-1 text-sm">Status: {{r.status}} <span v-if="r.status==='pending'&&!r.requester_id">· Awaiting approval and administrator invitation</span></p></div><div v-if="r.status==='rejected'" class="flex gap-2"><button :disabled="busy" class="rounded-lg border border-blue-600 px-4 py-2 text-sm font-semibold text-blue-600 disabled:opacity-40" @click="rejectedAction={request:r,action:'reconsider'}">Reconsider</button><button :disabled="busy" class="rounded-lg border border-red-600 px-4 py-2 text-sm font-semibold text-red-600 disabled:opacity-40" @click="rejectedAction={request:r,action:'delete'}">Delete</button></div><div v-if="r.status==='approved'&&r.created_school_id" class="flex gap-2"><button :disabled="!!inviteBusy" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40" @click="inviteAdmin(r)">{{inviteBusy===r.id?'Sending…':'Send admin invite'}}</button></div><div v-if="r.status==='pending'" class="flex gap-2"><button :disabled="busy" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40" @click="reviewAction={request:r,approve:true}">Approve</button><button :disabled="busy" class="rounded-lg border border-[var(--border)] px-4 py-2 text-sm" @click="reviewAction={request:r,approve:false}">Reject</button></div></div></div><p v-if="!filteredRequests.length" class="text-sm text-[var(--muted)]">No requests found.</p></UiPanel></template>
<div v-if="modalOpen&&selected" class="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" @click.self="modalOpen=false">
<section role="dialog" aria-modal="true" aria-label="School details" class="w-full max-w-2xl rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl">
<UiHoverScrollbar max-height="calc(90vh - 48px)">
<header class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">{{editing?'Edit school':'School details'}}</h2><div class="flex items-center gap-3"><button v-if="!editing&&!selected.deactivated_at" aria-label="Edit school" title="Edit school" class="rounded-lg border border-[var(--border)] p-2 text-blue-600" @click="editing=true"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m16 5 3 3M4 20l4.5-1 11-11a2.12 2.12 0 0 0-3-3l-11 11L4 20Z"/></svg></button><button aria-label="Close" @click="modalOpen=false" class="text-[#991B1B]"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg></button></div></header>
<div class="space-y-3">
<div class="rounded-xl bg-[var(--panel)] p-4"><p class="mb-2 text-xs text-[var(--muted)]">School name</p><input v-if="editing" v-model="name" required minlength="2" maxlength="160" aria-label="School name" class="w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/><strong v-else>{{selected.name}}</strong></div>
<div class="rounded-xl bg-[var(--panel)] p-4"><p class="mb-2 text-xs text-[var(--muted)]">School code</p><input v-if="editing" v-model="code" maxlength="30" aria-label="School code" class="w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/><strong v-else>{{selected.code||'Not set'}}</strong></div>
<div class="rounded-xl bg-[var(--panel)] p-4"><p class="text-xs text-[var(--muted)]">Status</p><strong>{{selected.deactivated_at?'Inactive':'Active'}}</strong></div>
<div class="rounded-xl bg-[var(--panel)] p-4"><h3 class="mb-2 font-semibold">School email domains</h3><p class="mb-3 text-xs text-[var(--muted)]">Verification and domain changes are managed separately.</p><div v-for="d in domains" :key="d.domain" class="border-b border-[var(--border)] py-2 text-sm">{{d.domain}} · {{d.is_verified?'Verified':'Unverified'}}{{d.is_primary?' · Primary':''}}</div><p v-if="!domains.length" class="text-sm text-[var(--muted)]">No domains configured.</p></div>
</div>
<div class="mt-5 flex justify-end gap-3"><button aria-label="Cancel" title="Cancel" class="rounded-xl border border-[var(--border)] px-5 py-3" @click="editing?resetEdit():modalOpen=false"><span class="text-[#991B1B]"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg></span></button><button aria-label="Save" title="Save" v-if="editing" class="rounded-xl bg-blue-600 px-5 py-3 font-semibold text-white inline-flex items-center gap-2" :disabled="busy||name.trim().length<2" @click="confirmSave=true"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8M7 3v5h8"/></svg></button></div>
</UiHoverScrollbar></section></div>
<div v-if="confirmSave" class="fixed inset-0 z-[60] grid place-items-center bg-black/70 p-4"><section role="alertdialog" aria-modal="true" class="w-full max-w-sm rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><h3 class="text-lg font-bold">Are you sure you wish to save these changes?</h3><p class="mt-3 text-sm">School: <strong>{{selected?.name}}</strong>. Update its settings?</p><div class="mt-6 flex justify-end gap-3"><button aria-label="Cancel" title="Cancel" class="rounded-xl border border-[var(--border)] px-4 py-2" @click="confirmSave=false"><span class="text-[#991B1B]"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg></span></button><button aria-label="Save" title="Save" class="rounded-xl bg-blue-600 px-4 py-2 text-white" :disabled="busy" @click="save"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8M7 3v5h8"/></svg></button></div></section></div>
</div><div v-if="rejectedAction" class="fixed inset-0 z-[100] grid place-items-center bg-black/60 p-4" @click.self="rejectedAction=null"><section role="dialog" aria-modal="true" aria-labelledby="rejected-action-title" class="w-full max-w-md rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><h2 id="rejected-action-title" class="text-xl font-bold">{{rejectedAction.action==='delete'?'Are you sure you wish to permanently delete this request?':'Are you sure you wish to reconsider this request?'}}</h2><p class="mt-3">School: <strong>{{rejectedAction.request.school_name}}</strong></p><p class="mt-2 text-sm">{{rejectedAction.action==='delete'?'This permanently deletes the rejected request and cannot be undone.':'This returns the request to Pending so it can be reviewed again.'}}</p><div class="mt-6 flex justify-end gap-3"><button :disabled="busy" class="rounded-lg border border-[var(--border)] px-4 py-2" @click="rejectedAction=null">Cancel</button><button :disabled="busy" class="rounded-lg px-4 py-2 font-semibold text-white disabled:opacity-40" :class="rejectedAction.action==='delete'?'bg-red-700':'bg-blue-600'" @click="confirmRejectedAction">{{busy?'Working…':rejectedAction.action==='delete'?'Delete request':'Reconsider request'}}</button></div></section></div><div v-if="reviewAction" class="fixed inset-0 z-[110] grid place-items-center bg-black/70 p-4"><section role="alertdialog" aria-modal="true" aria-labelledby="review-confirm-title" class="w-full max-w-md rounded-2xl bg-[var(--surface)] p-6 text-[var(--ink)] shadow-xl"><h2 id="review-confirm-title" class="text-lg font-bold">{{reviewAction.approve?'Are you sure you wish to approve this school?':'Are you sure you wish to reject this school request?'}}</h2><p class="mt-3 text-sm">School: <strong>{{reviewAction.request.school_name}}</strong></p><p class="mt-2 text-sm">{{reviewAction.approve?'Approval creates the school and enables administrator invitation.':'The request will be marked as rejected and can be reconsidered later.'}}</p><div class="mt-6 flex justify-end gap-3"><button :disabled="busy" class="rounded-xl border border-[var(--border)] px-4 py-2" @click="reviewAction=null">Cancel</button><button :disabled="busy" class="rounded-xl px-4 py-2 font-semibold text-white disabled:opacity-40" :class="reviewAction.approve?'bg-blue-600':'bg-red-700'" @click="review">{{busy?'Working…':reviewAction.approve?'Approve school':'Reject request'}}</button></div></section></div></template>